package com.hotel.controller;
import com.hotel.dao.impl.RoomDaoImpl; import com.hotel.exception.DataAccessException; import com.hotel.service.RoomAvailabilityService; import com.hotel.service.impl.RoomAvailabilityServiceImpl; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/receptionist/rooms/available") public class AvailableRoomServlet extends HttpServlet{private final RoomAvailabilityService service=new RoomAvailabilityServiceImpl(new RoomDaoImpl());protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{String rawId=q.getParameter("reservationRoomId");if(rawId==null||rawId.isBlank()){q.getRequestDispatcher("/WEB-INF/views/receptionist/rooms/available.jsp").forward(q,s);return;}try{long id=Long.parseLong(rawId);Integer floor=q.getParameter("floor")==null||q.getParameter("floor").isBlank()?null:Integer.valueOf(q.getParameter("floor"));var rooms=service.find(id,floor);if(rooms.isEmpty()){q.setAttribute("lookupError","Reservation room not found.");}else{q.setAttribute("rooms",rooms.get());}q.setAttribute("reservationRoomId",id);q.setAttribute("floor",floor);q.getRequestDispatcher("/WEB-INF/views/receptionist/rooms/available.jsp").forward(q,s);}catch(NumberFormatException e){q.setAttribute("lookupError","Reservation room ID and floor must be valid numbers.");q.getRequestDispatcher("/WEB-INF/views/receptionist/rooms/available.jsp").forward(q,s);}catch(DataAccessException e){getServletContext().log("Room availability failed",e);s.sendError(500);}}}
